-- Execute as actual API roles; a late failure must roll back status and totals.
begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into public.african_football_clubs(id,club_name,country_name,club_slug) overriding system value values (9960001,'Atomic QA','Rwanda','atomic-qa');
insert into public.partners(id,name,slug,is_active) values ('99600000-0000-4000-8000-000000000100','Atomic QA','atomic-qa',true);
insert into auth.users(id,aud,role,is_anonymous) values ('99600000-0000-4000-8000-000000000001','authenticated','authenticated',false);
insert into public.users(id,phone,full_name) values ('99600000-0000-4000-8000-000000000001','+250799600001','Atomic QA');
insert into public.profiles(id,club_id) values ('99600000-0000-4000-8000-000000000001',9960001);
insert into public.initiatives(id,partner_id,club_id,title,category) values ('99600000-0000-4000-8000-000000000200','99600000-0000-4000-8000-000000000100',9960001,'Atomic campaign','club');
insert into public.initiative_contributions(id,initiative_id,user_id,club_id,amount,status,momo_reference)
select ('99600000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'99600000-0000-4000-8000-000000000200','99600000-0000-4000-8000-000000000001',9960001,1000,case when n=302 then 'cancelled' else 'pending' end,'RS-SUPPORT-ATOMIC-'||n from generate_series(301,304) n;
select ok(not (select prosecdef from pg_proc where oid='public.confirm_club_initiative_contribution(uuid,uuid,text,integer)'::regprocedure),'confirmation uses caller privileges');
select ok(not has_function_privilege('anon','public.confirm_club_initiative_contribution(uuid,uuid,text,integer)','execute'),'anonymous execution denied');
select ok(not has_function_privilege('authenticated','public.confirm_club_initiative_contribution(uuid,uuid,text,integer)','execute'),'supporter execution denied');
set local role authenticated;
select throws_ok($$select public.confirm_club_initiative_contribution(null,null,null,null)$$,'42501',null,'actual supporter RPC is denied');
reset role;
set local role service_role;
select is(public.confirm_club_initiative_contribution('99600000-0000-4000-8000-000000000301',null,'RS-SUPPORT-ATOMIC-301',1000)->>'status','manual_review','missing payer is rejected');
select is(public.confirm_club_initiative_contribution('99600000-0000-4000-8000-000000000301','99600000-0000-4000-8000-000000000002','RS-SUPPORT-ATOMIC-301',1000)->>'status','manual_review','foreign owner is rejected');
select is(public.confirm_club_initiative_contribution('99600000-0000-4000-8000-000000000301','99600000-0000-4000-8000-000000000001','WRONG',1000)->>'status','manual_review','reference mismatch is rejected');
select is(public.confirm_club_initiative_contribution('99600000-0000-4000-8000-000000000301','99600000-0000-4000-8000-000000000001','RS-SUPPORT-ATOMIC-301',1)->>'status','manual_review','amount mismatch is rejected');
select is(public.confirm_club_initiative_contribution('99600000-0000-4000-8000-000000000302','99600000-0000-4000-8000-000000000001','RS-SUPPORT-ATOMIC-302',1000)->>'status','manual_review','cancelled contribution stays cancelled');
select is((select raised_amount from public.initiatives where id='99600000-0000-4000-8000-000000000200'),0,'rejected requests change no total');
select is(public.confirm_club_initiative_contribution('99600000-0000-4000-8000-000000000301','99600000-0000-4000-8000-000000000001','RS-SUPPORT-ATOMIC-301',1000)->>'newly_confirmed','true','first exact confirmation commits');
select ok((select status='confirmed' and confirmed_at is not null from public.initiative_contributions where id='99600000-0000-4000-8000-000000000301'),'status and confirmation timestamp committed');
select is((select raised_amount from public.initiatives where id='99600000-0000-4000-8000-000000000200'),1000,'campaign receives exact amount');
select is((select supporter_count from public.initiatives where id='99600000-0000-4000-8000-000000000200'),1,'campaign receives one contribution count');
select is((select points from public.fan_memberships where user_id='99600000-0000-4000-8000-000000000001' and partner_id='99600000-0000-4000-8000-000000000100'),20,'existing reward arithmetic committed');
select is(public.confirm_club_initiative_contribution('99600000-0000-4000-8000-000000000301','99600000-0000-4000-8000-000000000001','RS-SUPPORT-ATOMIC-301',1000)->>'newly_confirmed','false','replay reports existing confirmation');
select is((select points from public.fan_memberships where user_id='99600000-0000-4000-8000-000000000001' and partner_id='99600000-0000-4000-8000-000000000100'),20,'replay awards no further points');
reset role;
create function pg_temp.fail_atomic_reward() returns trigger language plpgsql as $$begin raise exception 'Synthetic late reward failure'; end;$$;
create trigger qa_fail_atomic_reward before update on public.fan_memberships for each row execute function pg_temp.fail_atomic_reward();
set local role service_role;
select throws_ok($$select public.confirm_club_initiative_contribution('99600000-0000-4000-8000-000000000303','99600000-0000-4000-8000-000000000001','RS-SUPPORT-ATOMIC-303',1000)$$,'P0001','Synthetic late reward failure','late reward failure aborts operation');
select ok((select status='pending' and confirmed_at is null from public.initiative_contributions where id='99600000-0000-4000-8000-000000000303'),'late failure rolls back contribution state');
select is((select raised_amount from public.initiatives where id='99600000-0000-4000-8000-000000000200'),1000,'late failure rolls back campaign total');
reset role;
drop trigger qa_fail_atomic_reward on public.fan_memberships;
set local role service_role;
select is(public.confirm_club_initiative_contribution('99600000-0000-4000-8000-000000000303','99600000-0000-4000-8000-000000000001','RS-SUPPORT-ATOMIC-303',1000)->>'newly_confirmed','true','same request succeeds after late failure recovers');
select is((select raised_amount from public.initiatives where id='99600000-0000-4000-8000-000000000200'),2000,'successful retry adds amount once');
select is((select points from public.fan_memberships where user_id='99600000-0000-4000-8000-000000000001' and partner_id='99600000-0000-4000-8000-000000000100'),40,'successful retry awards points once');
reset role;
select * from finish();
rollback;
